SELECT SMLT_ID, SMLT_MDL_SN, SMLT_NM, SMLT_TYPE, CRTR_DT, EXCN_YMD, TMNL_ID, SLF_ID, PRNT_ID, FLT_SCHDL_RSRC_ID, BAG_ALCTN_RSRC_ID, CKNCT_ALCTN_RSRC_ID, PRPT_SET_RSRC_ID, MDL_RSRC_ID, EXCN_ID, CKNCT_SRVC_HR_RSRC_ID, CHKN_TYPE_RSRC_ID, FCLTY_OPNG_DPTCNY_SRNG_RSRC_ID, FCLTY_OPNG_EMI_RSRC_ID, FCLTY_OPNG_IMMI_RSRC_ID, FCLTY_OPNG_SCRTY_CNTRL_RSRC_ID, FCLTY_OPNG_TR_SCRTY_CNTRL_RSRC_ID, SBD_CNTRL_ALCTN_ID, PLAN_BGNG_DT, PLAN_END_DT, SMLT_BGNG_DT, SMLT_END_DT, BDPSG_ANCE_YN FROM PMOWN.TN_PM_SMLT_STNG WHERE 1 = 1
AND SMLT_ID = #{smltId}
AND EXCN_YMD = #{excnYmd}
AND SMLT_TYPE = #{smltType}
